CREATE TABLE IF NOT EXISTS rooms (id TEXT PRIMARY KEY, created_at INTEGER NOT NULL, phase TEXT NOT NULL DEFAULT 'focus', phase_ends_at INTEGER NOT NULL, remaining INTEGER NOT NULL DEFAULT 1500, paused INTEGER NOT NULL DEFAULT 0, sprint INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id), owner_id TEXT NOT NULL, client_hash TEXT NOT NULL, name TEXT NOT NULL, task TEXT NOT NULL DEFAULT '', drift REAL NOT NULL DEFAULT 0, last_seen INTEGER NOT NULL, UNIQUE(room_id,owner_id,client_hash));
CREATE INDEX IF NOT EXISTS members_room_seen ON members(room_id,last_seen);
CREATE TABLE IF NOT EXISTS jolts (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id TEXT NOT NULL REFERENCES rooms(id), sender_id TEXT NOT NULL, target_id TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS jolts_room_id ON jolts(room_id,id);
CREATE INDEX IF NOT EXISTS jolts_sender_time ON jolts(sender_id,created_at);
ALTER TABLE rooms ADD COLUMN focus_seconds INTEGER NOT NULL DEFAULT 1500;
ALTER TABLE rooms ADD COLUMN break_seconds INTEGER NOT NULL DEFAULT 300;
ALTER TABLE rooms ADD COLUMN total_sprints INTEGER NOT NULL DEFAULT 4;
ALTER TABLE rooms ADD COLUMN visibility TEXT NOT NULL DEFAULT 'public';
ALTER TABLE rooms ADD COLUMN host_id TEXT;
CREATE TABLE profiles (owner_id TEXT PRIMARY KEY, alias TEXT NOT NULL);
CREATE TABLE friendships (requester TEXT NOT NULL, target TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', PRIMARY KEY(requester,target));
UPDATE rooms SET phase_ends_at=CAST(strftime('%s','now') AS INTEGER)*1000+remaining*1000, paused=0 WHERE paused=1;
CREATE TABLE messages (id INTEGER PRIMARY KEY AUTOINCREMENT, sender TEXT NOT NULL, recipient TEXT NOT NULL, sender_member TEXT NOT NULL, sender_name TEXT NOT NULL, room_id TEXT NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX messages_recipient ON messages(recipient,id);
CREATE INDEX messages_sender ON messages(sender,created_at);
ALTER TABLE rooms ADD COLUMN first_break_seconds INTEGER NOT NULL DEFAULT 300;
UPDATE rooms SET first_break_seconds=break_seconds;
ALTER TABLE rooms ADD COLUMN title TEXT NOT NULL DEFAULT '';
ALTER TABLE rooms ADD COLUMN password_hash TEXT;
CREATE TABLE room_invites (id TEXT PRIMARY KEY, room_id TEXT NOT NULL REFERENCES rooms(id), sender TEXT NOT NULL, recipient TEXT NOT NULL, created_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', UNIQUE(room_id,recipient));
CREATE INDEX room_invites_recipient ON room_invites(recipient,status);
CREATE TABLE room_access_attempts (room_id TEXT NOT NULL, owner_id TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, last_attempt INTEGER NOT NULL, PRIMARY KEY(room_id,owner_id));
CREATE TABLE appearance_presets (
 owner_id TEXT PRIMARY KEY,
 preset_json TEXT NOT NULL,
 updated_at INTEGER NOT NULL
);
CREATE TABLE profile_photos (owner_id TEXT PRIMARY KEY, object_key TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE voice_members (member_id TEXT PRIMARY KEY, room_id TEXT NOT NULL, session_id TEXT NOT NULL, muted INTEGER NOT NULL DEFAULT 0, last_seen INTEGER NOT NULL);
CREATE INDEX voice_room_presence ON voice_members(room_id,last_seen);
CREATE TABLE huddle_signals (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id TEXT NOT NULL, sender TEXT NOT NULL, sender_session TEXT NOT NULL, recipient TEXT NOT NULL, recipient_session TEXT NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX huddle_recipient ON huddle_signals(recipient,id);
CREATE TABLE room_chat (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id TEXT NOT NULL, sender TEXT NOT NULL, owner_id TEXT NOT NULL, name TEXT NOT NULL, text TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX room_chat_trail ON room_chat(room_id,id);
ALTER TABLE rooms ADD COLUMN first_focus_seconds INTEGER;
CREATE TABLE companion_pairs (
 id TEXT PRIMARY KEY,
 join_hash TEXT NOT NULL UNIQUE,
 writer_hash TEXT NOT NULL,
 viewer_hash TEXT,
 join_expires INTEGER NOT NULL,
 expires INTEGER NOT NULL,
 snapshot TEXT NOT NULL DEFAULT '{}',
 updated_at INTEGER NOT NULL,
 created_at INTEGER NOT NULL,
 ip_hash TEXT NOT NULL,
 pending_jolt TEXT
);
CREATE INDEX companion_expiry ON companion_pairs(expires);
CREATE INDEX companion_creation_ip ON companion_pairs(ip_hash,created_at);
CREATE TABLE IF NOT EXISTS companion_phone_events (
 pair_id TEXT NOT NULL REFERENCES companion_pairs(id) ON DELETE CASCADE,
 id TEXT NOT NULL,
 session_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('enabled','disabled','pickup')),
 at INTEGER NOT NULL,
 received_at INTEGER NOT NULL,
 PRIMARY KEY(pair_id,id)
);
CREATE INDEX IF NOT EXISTS companion_phone_events_session ON companion_phone_events(pair_id,session_id,at);
-- Optional anonymous text-only public space. No private thought IDs or voice data.
CREATE TABLE cloud_thoughts (
 id TEXT PRIMARY KEY,
 owner_hash TEXT NOT NULL,
 nonce TEXT NOT NULL,
 text TEXT NOT NULL CHECK(length(text) BETWEEN 1 AND 160),
 created_at INTEGER NOT NULL,
 expires_at INTEGER NOT NULL,
 UNIQUE(owner_hash,nonce)
);
CREATE INDEX cloud_thoughts_expiry ON cloud_thoughts(expires_at,created_at);
CREATE INDEX cloud_thoughts_owner ON cloud_thoughts(owner_hash,created_at);
CREATE TABLE cloud_resonance (
 thought_id TEXT NOT NULL REFERENCES cloud_thoughts(id) ON DELETE CASCADE,
 actor_hash TEXT NOT NULL,
 created_at INTEGER NOT NULL,
 PRIMARY KEY(thought_id,actor_hash)
);
CREATE INDEX cloud_resonance_actor ON cloud_resonance(actor_hash,created_at);
-- Released thoughts have no author/session key. Erase legacy ownership links.
DROP INDEX IF EXISTS cloud_thoughts_owner;
ALTER TABLE cloud_thoughts RENAME COLUMN owner_hash TO release_key;
UPDATE cloud_thoughts SET release_key=lower(hex(randomblob(32))),nonce=lower(hex(randomblob(16)));
-- Short-lived abuse counters have no thought IDs or text and cannot identify releases.
CREATE TABLE cloud_release_windows (
 actor_hash TEXT NOT NULL,
 window_start INTEGER NOT NULL,
 period INTEGER NOT NULL,
 hits INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(actor_hash,window_start,period)
);
-- A rolling one-minute send cooldown, separate from anonymous thought records.
CREATE TABLE cloud_release_cooldowns (
 actor_hash TEXT PRIMARY KEY,
 last_at INTEGER NOT NULL
);
CREATE TABLE room_removals(room_id TEXT NOT NULL REFERENCES rooms(id),owner_id TEXT NOT NULL,removed_at INTEGER NOT NULL,PRIMARY KEY(room_id,owner_id));
